    // G = [[D11, D12, 0], [D12, D22, 0], [0, 0, D66]]
    // So D(1)=D11, D(2)=D12, D(3)=0, D(4)=D12, D(5)=D22, D(6)=0, D(7)=0, D(8)=0, D(9)=D66
    double D_mat_1 = D11;   // D(1)
    double D_mat_2 = D12;   // D(2)
    double D_mat_3 = 0.0;   // D(3)
    double D_mat_4 = D12;   // D(4)
    double D_mat_5 = D22;   // D(5)
    double D_mat_6 = 0.0;   // D(6)
    double D_mat_7 = 0.0;   // D(7)
    double D_mat_8 = 0.0;   // D(8)
    double D_mat_9 = D66;   // D(9)

