    KX(1,1) = D_mat_9;   // A(8) = D(9) = D66
    KX(1,2) = D_mat_6;   // A(9) = D(6) = 0
    KX(1,3) = D_mat_3 * XBAR3; // A(10) = 0
    KX(1,4) = D_mat_6 * XBAR + YBAR2 * D_mat_9; // A(11) = 0 + YBAR2 * D66
