    KX(2,1) = D_mat_6;   // A(14) = D(6) = 0
    KX(2,2) = D_mat_5;   // A(15) = D(5) = D22
    KX(2,3) = D_mat_2 * XBAR3; // A(16)
    KX(2,4) = D_mat_5 * XBAR + YBAR2 * D_mat_6; // A(17) = D22 * XBAR
