    KX(4,5) = D_mat_5 * 3.0 * PXY2 + 6.0 * PY2 * D_mat_6; // A(30) = D22 * 3 * PXY2

    KX(5,0) = D_mat_2 * YBAR3; // A(31)
    KX(5,1) = D_mat_6 * YBAR3; // A(32) = 0
    KX(5,2) = D_mat_5 * YBAR3; // A(33)
    KX(5,3) = D_mat_2 * 9.0 * PXY2; // A(34) = A(24)
    KX(5,4) = KX(4,5); // A(35) = A(30)
