    H(3,4) = YCSQ * XSUBC;            // A(59)
    H(3,5) = YCSQ * YSUBC;            // A(60)
    H(4,1) = XSUBC;                   // A(62)
    H(4,2) = 2.0 * YSUBC;             // A(63)
    H(4,4) = 2.0 * XCYC;              // A(65)
    H(4,5) = 3.0 * YCSQ;              // A(66)
    H(5,0) = -2.0 * XSUBC;            // A(67)
    H(5,1) = -YSUBC;                  // A(68)
    H(5,3) = -3.0 * XCSQ;             // A(70)
    H(5,4) = -YCSQ;                   // A(71)

