    // DOF ordering: [w1, rx1, ry1, w2, rx2, ry2, w3, rx3, ry3]
    // The 9x9 matrix is composed of nine 3x3 blocks:
    // [ KAA      KIA.topRows(3)    KIA.bottomRows(3) ]
    // [ KIA.topRows(3).transpose()  KII.topLeftCorner(3,3)  KII.topRightCorner(3,3) ]
    // [ KIA.bottomRows(3).transpose()  KII.bottomLeftCorner(3,3)  KII.bottomRightCorner(3,3) ]

    Eigen::Matrix<double, 9, 9> K_global = Eigen::Matrix<double, 9, 9>::Zero();

    // Top row: KAA, KIA.topRows(3), KIA.bottomRows(3)
    K_global.block<3,3>(0,0) = KAA;
    K_global.block<3,3>(0,3) = KIA.topRows(3);
    K_global.block<3,3>(0,6) = KIA.bottomRows(3);

    // Middle row: KIA.topRows(3).transpose(), KII.topLeftCorner(3,3), KII.topRightCorner(3,3)
    K_global.block<3,3>(3,0) = KIA.topRows(3).transpose();
    K_global.block<3,3>(3,3) = KII.topLeftCorner(3,3);
    K_global.block<3,3>(3,6) = KII.topRightCorner(3,3);

    // Bottom row: KIA.bottomRows(3).transpose(), KII.bottomLeftCorner(3,3), KII.bottomRightCorner(3,3)
    K_global.block<3,3>(6,0) = KIA.bottomRows(3).transpose();
    K_global.block<3,3>(6,3) = KII.bottomLeftCorner(3,3);
    K_global.block<3,3>(6,6) = KII.bottomRightCorner(3,3);

    // Make sure the matrix is symmetric (it should be by construction, but ensure)
    for (int i = 0; i < 9; ++i) {
        for (int j = 0; j < i; ++j) {
            K_global(i,j) = K_global(j,i);
        }
    }

