    std::cout << "{\"stiffness_matrix\":[";
    for (int i = 0; i < 9; ++i) {
        std::cout << "[";
        for (int j = 0; j < 9; ++j) {
            std::cout << format_double(K_global(i,j));
            if (j < 8) std::cout << ",";
        }
        std::cout << "]";
        if (i < 8) std::cout << ",";
    }
